alter table public.material_decks add column if not exists is_public boolean not null default false;
alter table public.material_decks add column if not exists share_token text;
update public.material_decks set share_token=gen_random_uuid()::text where share_token is null;
alter table public.material_decks alter column share_token set not null;
create unique index if not exists material_decks_share_token_key on public.material_decks(share_token);
alter table public.material_decks alter column share_token set default gen_random_uuid()::text;
alter table public.word_lists add column if not exists is_public boolean not null default false;
alter table public.word_lists add column if not exists share_token text;
update public.word_lists set share_token=gen_random_uuid()::text where share_token is null;
alter table public.word_lists alter column share_token set not null;
create unique index if not exists word_lists_share_token_key on public.word_lists(share_token);
alter table public.word_lists alter column share_token set default gen_random_uuid()::text;
drop policy if exists "material decks public read" on public.material_decks;create policy "material decks public read" on public.material_decks for select using(is_public);
drop policy if exists "material nodes public read" on public.material_nodes;create policy "material nodes public read" on public.material_nodes for select using(exists(select 1 from public.material_decks d where d.id=deck_id and d.is_public));
drop policy if exists "word lists public read" on public.word_lists;create policy "word lists public read" on public.word_lists for select using(is_public);
drop policy if exists "word cards public read" on public.word_cards;create policy "word cards public read" on public.word_cards for select using(exists(select 1 from public.word_lists l where l.id=list_id and l.is_public));
create or replace function public.copy_shared_material(p_token text)returns uuid language plpgsql security definer set search_path=public as $$declare source_id uuid;new_deck uuid;n record;new_node uuid;node_map jsonb:='{}';begin if auth.uid()is null then raise exception'login required';end if;select id into source_id from material_decks where share_token=p_token and is_public;if source_id is null then raise exception'not found';end if;insert into material_decks(user_id,title,description)select auth.uid(),title,description from material_decks where id=source_id returning id into new_deck;for n in with recursive tree as(select mn.*,0 depth from material_nodes mn where deck_id=source_id and parent_id is null union all select child.*,tree.depth+1 from material_nodes child join tree on child.parent_id=tree.id)select*from tree order by depth,order_index loop insert into material_nodes(deck_id,parent_id,node_type,title,memo,order_index)values(new_deck,case when n.parent_id is null then null else(node_map->>n.parent_id::text)::uuid end,n.node_type,n.title,n.memo,n.order_index)returning id into new_node;node_map:=node_map||jsonb_build_object(n.id::text,new_node::text);end loop;return new_deck;end$$;
create or replace function public.copy_shared_cards(p_token text)returns uuid language plpgsql security definer set search_path=public as $$declare source_id uuid;new_list uuid;begin if auth.uid()is null then raise exception'login required';end if;select id into source_id from word_lists where share_token=p_token and is_public;if source_id is null then raise exception'not found';end if;insert into word_lists(user_id,title,description)select auth.uid(),title,description from word_lists where id=source_id returning id into new_list;insert into word_cards(list_id,card_id,front,back,memo,order_index)select new_list,card_id,front,back,memo,order_index from word_cards where list_id=source_id;return new_list;end$$;
